function Nut({ onChon, nhan }) {
  return <button onClick={() => onChon(nhan)}>{nhan}</button>;
}

function App() {
  const chon = (m) => console.log("Chon:", m);
  return (
    <div>
      <Nut nhan="A" onChon={chon} />
      <Nut nhan="B" onChon={chon} />
    </div>
  );
}

export default App;
